#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    //暴力方法1：先枚举后验证
    //暴力方法2：打表
    //以下是回溯+剪枝方法
    //核心在于：记录左右括号数量，保证必定有：左括号数量>=右括号数量
    vector<string> generateParenthesis(int n) {
    vector<string> res;
    string tmp;
    dfs(0,0,res,tmp,n);
    return res;        
    }

    void dfs(int left,int right,vector<string> &res,string &tmp,int n){
        //截止条件
        if(left == n && right == n){
            res.push_back(tmp);
            return ;
        }
        //剪枝的两个核心要点:1、left一定小于n，2、right一定小于left
        if(left < n){
            //回溯经典写法
            tmp.push_back('(');
            dfs(left+1,right,res,tmp,n);
            tmp.pop_back();
        }
        if(right<left){
            //同上
            tmp.push_back(')');
            dfs(left,right+1,res,tmp,n);
            tmp.pop_back();
        }
    }
};

